                if (window.scrollY < 1700) {
                    bottomStripSec.classList.add("d-none");
                } else {
                    bottomStripSec.classList.remove("d-none");
                }
            });
        });
    </script>


    <script defer>
        function getTimeRemaining(endTime) {
            const total = Date.parse(endTime) - Date.parse(new Date());
            const seconds = Math.floor((total / 1000) % 60);
            const minutes = Math.floor((total / 1000 / 60) % 60);
            const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
            const days = Math.floor(total / (1000 * 60 * 60 * 24));

            return {
                total,
                days,
                hours,
                minutes,
                seconds
            };
        }

        function getEndTime() {
            return new Date(2026, 0, 24, 23, 59, 59); // 24 January 2026
        }

        function padZero(number) {
            return number < 10 ? '0' + number : number;
        }

        function initializeClock() {
            const countdownElement = document.getElementById('countdown');
            const countdownElement2 = document.getElementById('countdown2');

            // Add null check
            if (!countdownElement && !countdownElement2) {
                console.warn('Countdown elements not found');
                return;
            }

            const endTime = getEndTime();

            function updateClock() {
                const t = getTimeRemaining(endTime);

                if (countdownElement) {
                    countdownElement.innerHTML = `
                    <p><span>${padZero(t.days)}</span>Days</p> :
                    <p><span>${padZero(t.hours)}</span>Hours</p> :
                    <p><span>${padZero(t.minutes)}</span>Minutes</p> :
                    <p><span>${padZero(t.seconds)}</span>Seconds</p>
                `;
                }

                if (countdownElement2) {
                    countdownElement2.innerHTML = `
                    <p><span>${padZero(t.days)}</span>Days</p>
                    <p><span>${padZero(t.hours)}</span>Hours</p>
                    <p><span>${padZero(t.minutes)}</span>Minutes</p>
                    <p><span>${padZero(t.seconds)}</span>Seconds</p>
                `;
                }

                if (t.total <= 0) {
                    clearInterval(timeInterval);
                    if (countdownElement) countdownElement.innerHTML = "Time's up!";
                    if (countdownElement2) countdownElement2.innerHTML = "Time's up!";
                }
            }

            updateClock();
            const timeInterval = setInterval(updateClock, 1000);
        }


        // Only use DOMContentLoaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initializeClock);
        } else {
            // DOM is already loaded
            initializeClock();
        }

        // Set displayed date text
        document.getElementById("month-last-date2").textContent = "24 January 2026";
    </script>

    <script>
        // Fallback for browsers that don’t support requestIdleCallback
        window.requestIdleCallback = window.requestIdleCallback || function (cb) {
            return setTimeout(cb, 1);
        };

        requestIdleCallback(() => {
            const swiperScript = document.createElement("script");
            swiperScript.src = "https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js";
            swiperScript.onload = () => {
                const configs = {
                    mySwiper2: 4,
                    // mySwiper3: 2,
                    // mySwiper4: 3,
                    mySwiper5: 4,
                    mySwiper6: 2,
                    mySwiper7: 2,
                };

                Object.entries(configs).forEach(([className, slidesView]) => {
                    new Swiper(`.${className}`, {
                        slidesPerView: slidesView,
                        spaceBetween: 30,
                        loop: true,
                        freeMode: true,
                        breakpoints: {
                            280: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            320: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            480: {
                                slidesPerView: 2,
                                spaceBetween: 10
                            },
                            768: {
                                slidesPerView: Math.max(2, slidesView - 1),
                                spaceBetween: 10,
                            },
                            1200: {
                                slidesPerView: slidesView,
                                spaceBetween: 10
                            },
                        },
                        autoplay: {
                            delay: 3500,
                            disableOnInteraction: true,
                            pauseOnMouseEnter: true,
                        },
                        navigation: {
                            nextEl: `.swiper-button-next${className.slice(-1)}`,
                            prevEl: `.swiper-button-prev${className.slice(-1)}`,
                        },
                        pagination: {
                            el: `.swiper-pagination${className.slice(-1)}`,
                            clickable: true,
                        },
                    });
                });
            };
            document.body.appendChild(swiperScript);
        });
    </script>


    <script>
        document.addEventListener("DOMContentLoaded", () => {
            const cards = document.querySelectorAll(".testimonial-card");

            cards.forEach((card) => {
                const text = card.querySelector(".testimonial-text");
                const btn = card.querySelector(".read-more-btn");
                setTimeout(() => {
                    const isClamped = text.scrollHeight > text.clientHeight;

                    if (!isClamped) {
                        btn.style.display = "none";
                    }
                }, 100);

                btn.addEventListener("click", () => {
                    text.classList.toggle("expanded");
                    btn.textContent = text.classList.contains("expanded") ?
                        "Read less" :
                        "Read more";
                });
            });
        });
    </script>
