            ];

            // Calculate position for floating icon wrapper
            function moveFloatingIcon(index) {
                const tab = tabs[index];
                const tabRect = tab.getBoundingClientRect();
                const containerRect = menuContainer.getBoundingClientRect();

                // Calculate center position of the clicked tab relative to the container
                const tabCenter = tabRect.left + (tabRect.width / 2) - containerRect.left;
                const iconOffset = 40; // Half of floating icon width (80px / 2)

                floatingIconWrapper.style.left = `${tabCenter - iconOffset}px`;
                floatingIcon.innerHTML = tabIcons[index];
            }

            tabs.forEach((tab, index) => {
                tab.addEventListener('click', function () {
                    const targetTab = this.getAttribute('data-tab');

                    // Remove active class from all tabs
                    tabs.forEach(t => t.classList.remove('active'));

                    // Add active class to clicked tab
                    this.classList.add('active');

                    // Move and update floating icon
                    moveFloatingIcon(index);
                    floatingIcon.classList.add('active');

                    // Hide all cards with fade out
                    cards.forEach(card => {
                        card.classList.remove('show');
                        setTimeout(() => {
                            card.style.display = 'none';
                        }, 300);
                    });

                    // Show relevant cards with staggered animation
                    setTimeout(() => {
                        const targetCards = document.querySelectorAll(
                            `[data-content="${targetTab}"]`);
                        targetCards.forEach((card, cardIndex) => {
                            card.style.display = 'block';
                            setTimeout(() => {
                                card.classList.add('show');
                            }, cardIndex * 150);
                        });
                    }, 350);
                });
            });

            // Initialize position on load
            moveFloatingIcon(0);
        });
    </script>

    <!-- Tab pane for faq -->
    <script defer>
        document.querySelectorAll('.faq-tab').forEach(tab => {
            tab.addEventListener('click', function () {
                const targetTab = this.getAttribute('data-tab');

                // Remove active class from all tabs (both desktop and mobile)
                document.querySelectorAll('.faq-tab').forEach(t => t.classList.remove('active'));

                // Add active class to both corresponding tabs (desktop and mobile)
                document.querySelectorAll(`[data-tab="${targetTab}"]`).forEach(t => t.classList.add(
                    'active'));

                // Hide all content
                document.querySelectorAll('.tab-content').forEach(content => {
                    content.style.display = 'none';
                });

                // Show target content
                document.getElementById(targetTab).style.display = 'block';

                // Collapse all accordions in the new tab and expand the first one
                const targetAccordion = document.querySelector(`#${targetTab} .accordion`);
                if (targetAccordion) {
                    const allCollapses = targetAccordion.querySelectorAll('.accordion-collapse');
                    allCollapses.forEach((collapse, index) => {
                        if (index === 0) {
                            collapse.classList.add('show');
                            collapse.previousElementSibling.querySelector('.accordion-button')
                                .classList.remove('collapsed');
                        } else {
                            collapse.classList.remove('show');
                            collapse.previousElementSibling.querySelector('.accordion-button')
                                .classList.add('collapsed');
                        }
                    });
                }
            });
        });
    </script>
